/* From Uiverse.io by ahmed150up - Tags: pause, play, music, soundCloud */
.__UIV_SCOPE__ .audio-player {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 300px;
  height: 80px;
  background-color: #f3f3f3;
  border-radius: 8px;
  padding: 8px;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .player-controls {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .song-info {
  margin-bottom: 4px;
}

.__UIV_SCOPE__ .song-title {
  font-size: 16px;
  color: #333;
  margin: 0;
}

.__UIV_SCOPE__ .artist {
  font-size: 12px;
  color: #666;
  margin: 0;
}

.__UIV_SCOPE__ .progress-bar {
  width: 100%;
  height: 4px;
  background-color: #ddd;
  border-radius: 2px;
  overflow: hidden;
}

.__UIV_SCOPE__ .progress {
  width: 0;
  height: 100%;
  background-color: #ff5500;
  animation: progress-animation 10s linear infinite;
}

.__UIV_SCOPE__ .buttons {
  display: flex;
  align-items: center;
  margin-top: 4px;
}

.__UIV_SCOPE__ button {
  background: none;
  border: none;
  cursor: pointer;
  outline: none;
}

.__UIV_SCOPE__ .play-btn,
.__UIV_SCOPE__ .pause-btn,
.__UIV_SCOPE__ .skip-btn,
.__UIV_SCOPE__ .volume-btn {
  font-size: 16px;
  color: #666;
  margin-right: 8px;
  transition: transform 0.2s ease-in-out;
}

.__UIV_SCOPE__ .play-btn:hover,
.__UIV_SCOPE__ .pause-btn:hover,
.__UIV_SCOPE__ .skip-btn:hover,
.__UIV_SCOPE__ .volume-btn:hover {
  transform: scale(1.2);
}

.__UIV_SCOPE__ .volume-slider {
  width: 100px;
  height: 5px;
  background-color: #ccc;
  position: relative;
  margin-left: 10px;
}

.__UIV_SCOPE__ .volume-slider-bar {
  height: 100%;
  background-color: #666;
}

.__UIV_SCOPE__ .volume-slider-handle {
  width: 16px;
  height: 16px;
  background-color: #666;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  cursor: pointer;
}

@keyframes progress-animation {
  0% {
    width: 0;
  }

  100% {
    width: 100%;
  }
}
